from lib import R
F = "36-soups.txt"
def S(t, cu, prep, cook, serv, ings, steps, meals="Lunch, Dinner, Soup"):
    R(F, t, "Soup", cu, prep, cook, serv, meals, ings, steps)

# ---------------- smooth blended soups ----------------
# title, cuisine, vegetables, extra aromatics/spice, spice words, liquid, simmer, finish ings, finish words, fat
BL = [
 ("Creamy Cauliflower Soup", "French", "1|cauliflower, chopped; 1|potato, diced", "2 cloves|garlic; 0.25 tsp|nutmeg", "the garlic and nutmeg", "1 l|vegetable stock", 20, "100 ml|milk; 1 tbsp|chives, snipped", "the milk, and scatter with chives", "2 tbsp|butter"),
 ("Curried Parsnip Soup", "British", "600 g|parsnips, chopped; 1|apple, chopped", "2 tsp|curry powder; 1 tsp|ginger, grated", "the curry powder and ginger", "1 l|vegetable stock", 20, "100 ml|coconut milk", "the coconut milk", "2 tbsp|olive oil"),
 ("Pea and Mint Soup", "British", "500 g|frozen peas; 1|potato, diced", "1 clove|garlic", "the garlic", "900 ml|vegetable stock", 12, "1 handful|mint; 4 tbsp|creme fraiche", "the mint (blend it in), and swirl over creme fraiche", "1 tbsp|butter"),
 ("Spiced Pumpkin Soup", "American", "1 kg|pumpkin, peeled and diced; 1|carrot, chopped", "1 tsp|cumin; 0.5 tsp|cinnamon; 0.25 tsp|nutmeg", "the cumin, cinnamon and nutmeg", "1 l|vegetable stock", 25, "100 ml|heavy cream; 2 tbsp|pumpkin seeds, toasted", "the cream, and top with toasted pumpkin seeds", "2 tbsp|butter"),
 ("Zucchini Basil Soup", "Italian", "4|zucchini, chopped; 1|potato, diced", "2 cloves|garlic", "the garlic", "900 ml|vegetable stock", 15, "1 handful|basil; 30 g|parmesan, grated", "the basil (blend it in), and top with parmesan", "2 tbsp|olive oil"),
 ("Watercress and Potato Soup", "British", "500 g|potatoes, diced; 150 g|watercress", "1 clove|garlic", "the garlic", "1 l|vegetable stock", 18, "100 ml|heavy cream", "the cream (add the watercress for the last 2 minutes before blending so it stays green)", "2 tbsp|butter"),
 ("Cream of Asparagus Soup", "French", "500 g|asparagus, chopped, tips reserved; 1|potato, diced", "1 clove|garlic", "the garlic", "900 ml|chicken stock", 15, "100 ml|heavy cream; 1|lemon", "the cream and a squeeze of lemon, and garnish with the blanched tips", "2 tbsp|butter"),
 ("Beet and Apple Soup with Dill", "Eastern European", "500 g|beets, peeled and diced; 1|apple, chopped; 1|carrot, chopped", "1 tsp|caraway seeds", "the caraway", "1 l|vegetable stock", 30, "4 tbsp|sour cream; 1 tbsp|dill, chopped; 1 tbsp|red wine vinegar", "the vinegar, and top with sour cream and dill", "2 tbsp|olive oil"),
 ("Sweet Corn Soup with Chili", "Mexican", "600 g|sweetcorn; 1|potato, diced", "1|jalapeno, chopped; 1 tsp|cumin", "the jalapeno and cumin", "900 ml|vegetable stock", 15, "1|lime; 1 handful|cilantro", "lime juice, and top with cilantro and a few reserved corn kernels", "2 tbsp|butter"),
 ("Spinach and Potato Soup", "Irish", "600 g|potatoes, diced; 200 g|spinach", "2 cloves|garlic; 0.25 tsp|nutmeg", "the garlic and nutmeg", "1 l|vegetable stock", 18, "100 ml|milk", "the milk (add the spinach for the last minute before blending)", "2 tbsp|butter"),
 ("Smoky Tomato and Chipotle Soup", "Mexican", "2 can|canned tomatoes; 1|red bell pepper, chopped", "1|chipotle pepper in adobo; 1 tsp|smoked paprika; 2 cloves|garlic", "the chipotle, paprika and garlic", "600 ml|vegetable stock", 20, "4 tbsp|sour cream; 1 handful|tortilla chips", "and top with sour cream and crushed tortilla chips", "2 tbsp|olive oil"),
 ("Green Broccoli and Spinach Soup", "International", "500 g|broccoli, chopped; 100 g|spinach; 1|zucchini, chopped", "2 cloves|garlic; 1 tsp|ginger, grated", "the garlic and ginger", "1 l|vegetable stock", 12, "1|lemon; 2 tbsp|pumpkin seeds", "a squeeze of lemon, and top with pumpkin seeds", "2 tbsp|olive oil"),
 ("Red Pepper and Sweet Potato Soup", "International", "2|red bell peppers, chopped; 2|sweet potatoes, diced", "1 tsp|smoked paprika; 1 tsp|cumin", "the paprika and cumin", "1 l|vegetable stock", 20, "4 tbsp|yogurt", "and swirl in the yogurt", "2 tbsp|olive oil"),
 ("Cream of Celery Soup", "French", "1 head|celery, chopped; 1|potato, diced", "1 clove|garlic; 1 tsp|dried thyme", "the garlic and thyme", "900 ml|chicken stock", 25, "100 ml|heavy cream", "the cream", "2 tbsp|butter"),
]
for t, cu, veg, aro, aro_w, liq, mins, fin_i, fin_w, fat in BL:
    S(t, cu, 15, mins + 10, 4, fat + "; 1|onion, chopped; " + veg + "; " + aro + "; " + liq + "; |salt; |black pepper; " + fin_i,
      ["Melt or heat the " + fat.split("|")[1] + " in a large pot and soften the onion gently for 5 minutes",
       "Add the vegetables and " + aro_w + " and stir for 2 minutes",
       "Pour in the " + liq.split("|")[1] + ", bring to a boil and simmer for " + str(mins) + " minutes until everything is very tender",
       "Blend until smooth with a stick blender (or in batches in a blender, venting the lid). Season to taste",
       "Reheat gently and stir in " + fin_w if not fin_w.startswith("and") else "Reheat gently, ladle into bowls " + fin_w])

# ---------------- hearty bean, meat and vegetable soups ----------------
S("White Bean and Rosemary Soup", "Italian", 10, 25, 4, "3 tbsp|olive oil; 1|onion, chopped; 2|celery stalks, diced; 3 cloves|garlic; 2 sprigs|rosemary; 2 can|white beans, drained; 1 l|vegetable stock; 1|lemon; |salt; |black pepper",
  "Soften the onion and celery in the oil for 6 minutes, then add the garlic and rosemary for 1 minute / Add the beans and stock and simmer 15 minutes / Remove the rosemary and blend about half the soup, leaving the rest chunky / Season, add a squeeze of lemon and serve with a drizzle of olive oil")
S("Tuscan Sausage, Potato and Kale Soup", "Italian-American", 10, 30, 6, "400 g|italian sausages, meat squeezed out; 1|onion, chopped; 3 cloves|garlic; 600 g|potatoes, sliced; 1.2 l|chicken stock; 150 g|kale, shredded; 150 ml|heavy cream; 0.5 tsp|chili flakes; |salt",
  "Brown the sausage meat in a large pot, breaking it up, then add the onion and garlic for 5 minutes / Add the potatoes, stock and chili flakes and simmer 15 minutes until the potatoes are tender / Stir in the kale and cream and simmer 5 minutes more / Season and serve")
S("Lemony Lentil and Spinach Soup", "Middle Eastern", 10, 30, 4, "2 tbsp|olive oil; 1|onion, chopped; 2|carrots, diced; 3 cloves|garlic; 1 tsp|cumin; 200 g|brown lentils; 1.2 l|vegetable stock; 150 g|spinach; 1|lemon; |salt",
  "Soften the onion and carrots in the oil for 6 minutes, then add the garlic and cumin / Add the lentils and stock and simmer 25 minutes until the lentils are soft / Stir in the spinach until wilted / Add the juice of the lemon, season and serve")
S("Mulligatawny Soup", "Anglo-Indian", 15, 30, 6, "2 tbsp|vegetable oil; 1|onion, chopped; 2|carrots, diced; 1|apple, diced; 2 tbsp|curry powder; 100 g|red lentils; 300 g|chicken thighs, diced; 1.2 l|chicken stock; 200 ml|coconut milk; 100 g|rice, cooked",
  "Fry the onion, carrots and apple in the oil for 6 minutes / Stir in the curry powder for 1 minute, then add the chicken, lentils and stock / Simmer 25 minutes, then lift out the chicken, blend the soup until fairly smooth and return the chicken / Stir in the coconut milk and rice and heat through")
S("Black-Eyed Pea and Collard Soup", "Southern US", 10, 35, 6, "4 slices|bacon, chopped; 1|onion, chopped; 2|celery stalks, diced; 2 cloves|garlic; 2 can|black-eyed peas, drained; 1 can|canned tomatoes; 1.2 l|chicken stock; 200 g|collard greens, shredded; 1 tbsp|hot sauce; |salt",
  "Cook the bacon in a large pot until crisp, then soften the onion and celery in the fat / Add the garlic, peas, tomatoes and stock and simmer 15 minutes / Add the collards and simmer 15 minutes more until tender / Season with hot sauce and salt")
S("Taco Soup", "Tex-Mex", 10, 25, 6, "500 g|ground beef; 1|onion, chopped; 2 tbsp|taco seasoning; 1 can|black beans, drained; 1 can|kidney beans, drained; 1 can|canned tomatoes; 200 g|sweetcorn; 900 ml|beef stock; 100 g|cheddar, grated; 4 tbsp|sour cream",
  "Brown the beef with the onion, then stir in the taco seasoning / Add the beans, tomatoes, corn and stock and simmer 20 minutes / Serve topped with cheddar and sour cream, with tortilla chips if you like")
S("Cabbage Roll Soup", "Eastern European", 15, 35, 6, "400 g|ground beef; 1|onion, chopped; 2 cloves|garlic; 500 g|cabbage, chopped; 1 can|canned tomatoes; 1 l|beef stock; 80 g|rice; 1 tsp|paprika; 1 tbsp|brown sugar; 1 tbsp|apple cider vinegar; 4 tbsp|sour cream",
  "Brown the beef with the onion and garlic / Add the cabbage, tomatoes, stock, rice, paprika, sugar and vinegar / Simmer 30 minutes until the cabbage and rice are soft / Season and serve with sour cream")
S("Hungarian Goulash Soup", "Hungarian", 15, 90, 6, "700 g|stewing beef, in small cubes; 2 tbsp|vegetable oil; 2|onions, chopped; 2 tbsp|sweet paprika; 1 tsp|caraway seeds; 2 tbsp|tomato paste; 1.5 l|beef stock; 2|bell peppers, diced; 500 g|potatoes, diced; |salt",
  "Brown the beef in the oil in batches, then soften the onions in the same pot for 8 minutes / Off the heat stir in the paprika, caraway and tomato paste, then return the beef and add the stock / Cover and simmer 1 hour / Add the peppers and potatoes and simmer 25 minutes more until the beef is tender")
S("Chicken and Wild Rice Soup", "American", 15, 50, 6, "2 tbsp|butter; 1|onion, chopped; 2|carrots, diced; 2|celery stalks, diced; 150 g|wild rice; 1.5 l|chicken stock; 500 g|chicken breast; 1 tsp|dried thyme; 150 ml|heavy cream; 2 tbsp|flour",
  "Soften the onion, carrots and celery in the butter for 6 minutes, then stir in the flour / Add the wild rice, stock, thyme and whole chicken breasts and simmer 45 minutes until the rice is tender / Shred the chicken back into the pot / Stir in the cream, season and heat through")
S("Caldo Verde-Style Kale and Chorizo Soup", "Portuguese", 10, 30, 6, "3 tbsp|olive oil; 1|onion, chopped; 3 cloves|garlic; 700 g|potatoes, diced; 1.5 l|chicken stock; 150 g|chorizo, sliced; 200 g|kale, very finely shredded; |salt",
  "Soften the onion and garlic in the oil, add the potatoes and stock and simmer 20 minutes until soft / Mash or blend until fairly smooth / Fry the chorizo in a separate pan until crisp / Add the kale to the soup and simmer 5 minutes, then stir in the chorizo and its oil")
S("Stuffed Pepper Soup", "American", 10, 30, 6, "500 g|ground beef; 1|onion, chopped; 3|bell peppers, diced; 2 cloves|garlic; 2 can|canned tomatoes; 2 tbsp|tomato paste; 1 l|beef stock; 100 g|rice; 1 tsp|italian seasoning; 100 g|cheddar, grated",
  "Brown the beef with the onion, then add the peppers and garlic for 5 minutes / Add the tomatoes, tomato paste, stock, rice and seasoning / Simmer 20 minutes until the rice is tender / Serve topped with cheese")
S("Lasagna Soup", "Italian-American", 10, 30, 6, "400 g|ground beef; 1|onion, chopped; 3 cloves|garlic; 1 can|canned tomatoes; 2 tbsp|tomato paste; 1.2 l|chicken stock; 1 tsp|italian seasoning; 8|lasagna noodles, broken; 150 g|ricotta; 80 g|mozzarella, grated",
  "Brown the beef with the onion and garlic, then stir in the tomato paste / Add the tomatoes, stock and seasoning and bring to a boil / Add the broken noodles and simmer 12 to 15 minutes until tender / Serve topped with spoonfuls of ricotta and mozzarella")
S("Chickpea Noodle Soup", "American", 10, 20, 4, "2 tbsp|olive oil; 1|onion, chopped; 2|carrots, sliced; 2|celery stalks, sliced; 2 cloves|garlic; 1 tsp|dried thyme; 1.5 l|vegetable stock; 1 can|chickpeas, drained; 150 g|egg noodles; 1 handful|parsley, chopped",
  "Soften the onion, carrots and celery in the oil for 6 minutes / Add the garlic, thyme and stock and simmer 8 minutes / Add the chickpeas and noodles and cook until the noodles are tender / Season and finish with parsley")

# ---------------- noodle soups ----------------
S("Chicken Udon Soup", "Japanese", 10, 20, 4, "1.5 l|chicken stock; 3 tbsp|soy sauce; 2 tbsp|mirin; 1 tbsp|ginger, sliced; 400 g|chicken thighs, sliced; 400 g|udon noodles; 2|bok choy, quartered; 4|green onions, sliced",
  "Simmer the stock, soy sauce, mirin and ginger for 5 minutes / Add the chicken and simmer 8 minutes until cooked / Add the noodles and bok choy and cook 3 minutes / Ladle into bowls and top with green onions")
S("Laksa-Style Coconut Noodle Soup", "Malaysian", 15, 20, 4, "3 tbsp|laksa paste; 1 tbsp|vegetable oil; 800 ml|chicken stock; 400 ml|coconut milk; 1 tbsp|fish sauce; 1 tsp|sugar; 400 g|shrimp, peeled; 200 g|rice noodles; 100 g|bean sprouts; 1|lime; 1 handful|cilantro",
  "Fry the laksa paste in the oil for 2 minutes until fragrant / Add the stock, coconut milk, fish sauce and sugar and simmer 10 minutes / Cook the noodles separately and divide between bowls / Poach the shrimp in the soup for 3 minutes, then ladle over the noodles and top with bean sprouts, cilantro and lime")
S("Ginger Chicken Rice Noodle Soup", "Vietnamese", 10, 25, 4, "1.5 l|chicken stock; 5 cm|ginger, sliced; 1|onion, halved; 2 tbsp|fish sauce; 400 g|chicken breast; 200 g|rice noodles; 100 g|bean sprouts; 1 handful|basil; 1|lime; 1|red chili, sliced",
  "Simmer the stock with the ginger, onion and fish sauce for 10 minutes / Poach the chicken in it for 12 minutes, then lift out and shred / Cook the noodles, divide between bowls and add the chicken / Strain the broth over and top with bean sprouts, basil, chili and lime")
S("Spicy Kimchi Noodle Soup", "Korean", 5, 15, 2, "1 tbsp|sesame oil; 150 g|kimchi, chopped; 1 tbsp|gochujang; 800 ml|vegetable stock; 1 tbsp|soy sauce; 200 g|firm tofu, cubed; 2 packs|ramen noodles, seasoning discarded; 2|eggs; 2|green onions, sliced",
  "Fry the kimchi in the sesame oil for 2 minutes, then stir in the gochujang / Add the stock and soy sauce and simmer 5 minutes / Add the tofu and noodles and cook 3 minutes, cracking in the eggs to poach for the last 2 minutes / Top with green onions")
S("Tofu and Bok Choy Noodle Soup", "Chinese", 10, 15, 4, "1.5 l|vegetable stock; 3 tbsp|soy sauce; 1 tbsp|ginger, grated; 2 cloves|garlic, sliced; 300 g|firm tofu, cubed; 4|bok choy, halved; 250 g|wheat noodles; 1 tsp|sesame oil; 2|green onions, sliced",
  "Simmer the stock with the soy sauce, ginger and garlic for 5 minutes / Add the tofu and bok choy and simmer 4 minutes / Cook the noodles separately, then divide between bowls / Ladle over the soup and finish with sesame oil and green onions")
S("Chicken Pho-Style Noodle Soup", "Vietnamese", 15, 40, 4, "1.5 l|chicken stock; 1|onion, halved and charred; 5 cm|ginger, sliced and charred; 2|star anise; 1|cinnamon stick; 2 tbsp|fish sauce; 400 g|chicken breast; 250 g|rice noodles; 100 g|bean sprouts; 1 handful|basil; 1|lime",
  "Simmer the stock with the charred onion and ginger, star anise and cinnamon for 25 minutes, then strain / Add the fish sauce and poach the chicken for 12 minutes; slice it / Cook the noodles and divide between bowls with the chicken / Pour over the hot broth and serve with bean sprouts, basil and lime")
S("Sopa de Fideo", "Mexican", 10, 20, 4, "2 tbsp|vegetable oil; 200 g|vermicelli; 1 can|canned tomatoes; 0.5|onion; 2 cloves|garlic; 1.2 l|chicken stock; 1 tsp|cumin; 1 handful|cilantro; 1|lime",
  "Toast the vermicelli in the oil, stirring, until golden brown / Blend the tomatoes, onion and garlic and pour into the pot (it will splutter), cooking 3 minutes / Add the stock and cumin and simmer 10 minutes until the noodles are soft / Season and serve with cilantro and lime")
S("Chinese Tomato and Egg Soup", "Chinese", 5, 12, 4, "1 tbsp|vegetable oil; 3|tomatoes, in wedges; 1 l|chicken stock; 1 tbsp|soy sauce; 1 tsp|sugar; 1 tbsp|cornstarch; 2|eggs, beaten; 1 tsp|sesame oil; 2|green onions, sliced",
  "Fry the tomatoes in the oil for 3 minutes until soft / Add the stock, soy sauce and sugar and simmer 5 minutes / Stir in the cornstarch mixed with 2 tbsp water to thicken slightly / Drizzle in the eggs while stirring slowly to make ribbons, then add the sesame oil and green onions")

# ---------------- chowders and chilled soups ----------------
S("Salmon Chowder", "American", 15, 25, 4, "2 tbsp|butter; 1|onion, chopped; 2|celery stalks, diced; 500 g|potatoes, diced; 700 ml|fish stock; 300 ml|milk; 150 g|sweetcorn; 400 g|salmon fillet, cubed; 1 tbsp|dill, chopped; |salt",
  "Soften the onion and celery in the butter for 5 minutes / Add the potatoes and stock and simmer 12 minutes until tender / Add the milk, corn and salmon and simmer gently 5 minutes until the fish is just cooked / Season and finish with dill")
S("Fish Chowder", "New England", 15, 25, 4, "4 slices|bacon, chopped; 1|onion, chopped; 500 g|potatoes, diced; 600 ml|fish stock; 300 ml|milk; 100 ml|heavy cream; 500 g|white fish fillets, in chunks; 1 tsp|dried thyme; 1 tbsp|parsley, chopped",
  "Crisp the bacon in a pot, then soften the onion in the fat / Add the potatoes, thyme and stock and simmer 12 minutes / Add the milk, cream and fish and simmer very gently 5 minutes / Season and scatter with parsley")
S("Chicken Corn Chowder", "American", 15, 25, 6, "2 tbsp|butter; 1|onion, chopped; 1|red bell pepper, diced; 2 tbsp|flour; 1 l|chicken stock; 400 g|potatoes, diced; 400 g|sweetcorn; 300 g|cooked chicken, shredded; 200 ml|milk; |salt",
  "Soften the onion and pepper in the butter, then stir in the flour for 1 minute / Gradually add the stock, then the potatoes, and simmer 12 minutes / Add the corn, chicken and milk and simmer 5 minutes / Mash a few potatoes against the side to thicken and season")
S("Loaded Baked Potato Soup", "American", 15, 30, 6, "6 slices|bacon, chopped; 1|onion, chopped; 1 kg|potatoes, diced; 1 l|chicken stock; 200 ml|milk; 150 g|sour cream; 150 g|cheddar, grated; 3|green onions, sliced; |salt",
  "Crisp the bacon and set aside, keeping 1 tbsp fat in the pot / Soften the onion, add the potatoes and stock and simmer 15 minutes until very soft / Mash roughly, then stir in the milk, sour cream and most of the cheese / Serve topped with bacon, the rest of the cheese and green onions")
S("Shrimp and Corn Chowder", "Southern US", 15, 20, 4, "2 tbsp|butter; 1|onion, chopped; 1|celery stalk, diced; 1 tsp|old bay seasoning; 400 g|potatoes, diced; 600 ml|chicken stock; 400 g|sweetcorn; 300 ml|milk; 400 g|shrimp, peeled",
  "Soften the onion and celery in the butter with the Old Bay / Add the potatoes and stock and simmer 12 minutes / Add the corn and milk and blend a third of the soup to thicken / Add the shrimp and simmer 3 minutes until pink")
S("Chilled Cucumber Yogurt Soup", "Turkish", 15, 0, 4, "2|cucumbers, chopped; 500 g|yogurt; 1 clove|garlic; 1 handful|mint; 1 handful|dill; 2 tbsp|olive oil; 1|lemon; |salt",
  "Blend the cucumbers, yogurt, garlic, most of the herbs and half the lemon juice until smooth / Season and add cold water to thin if needed / Chill at least 1 hour / Serve with olive oil and the remaining herbs", "Lunch, Soup, Appetizer")
S("Watermelon Gazpacho", "Spanish", 15, 0, 4, "1 kg|watermelon, cubed; 2|tomatoes; 1|cucumber; 1|red onion, quartered; 1|jalapeno, seeded; 2 tbsp|red wine vinegar; 2 tbsp|olive oil; 1 handful|mint; |salt",
  "Blend the watermelon, tomatoes, three quarters of the cucumber, a little of the onion and the jalapeno until smooth / Season with the vinegar, oil and salt / Chill at least 1 hour / Serve topped with the rest of the cucumber, diced, and mint", "Lunch, Soup, Appetizer")
